typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);

#define NEW new(0, __FILE__, __LINE__)

class vm_stack;

class script_library_class {
    char data[32];

public:
    script_library_class(const char *, int, const char * = 0);
    virtual ~script_library_class();

    class function {
    protected:
        char *name;

    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };

        function(script_library_class *, const char *);
        virtual ~function();
        virtual bool operator()(vm_stack &, entry_t) { return true; }
    };
};

class slc_signaller_t : public script_library_class {
public:
    slc_signaller_t(const char *n, int sz, const char *p = 0)
        : script_library_class(n, sz, p) {}
};

class slf_signaller_enable_signals_t : public script_library_class::function {
public:
    slf_signaller_enable_signals_t(script_library_class *slc, const char *n)
        : script_library_class::function(slc, n) {}
};

class slf_signaller_disable_signals_t : public script_library_class::function {
public:
    slf_signaller_disable_signals_t(script_library_class *slc, const char *n)
        : script_library_class::function(slc, n) {}
};

class slf_signaller_clear_callbacks_t : public script_library_class::function {
public:
    slf_signaller_clear_callbacks_t(script_library_class *slc, const char *n)
        : script_library_class::function(slc, n) {}
};

class slf_signaller_clear_callback_t : public script_library_class::function {
public:
    slf_signaller_clear_callback_t(script_library_class *slc, const char *n)
        : script_library_class::function(slc, n) {}
};

void register_signal_lib()
{
    slc_signaller_t *slc_signaller = NEW slc_signaller_t("signaller", 4);

    NEW slf_signaller_enable_signals_t(slc_signaller, "enable_signals()");
    NEW slf_signaller_disable_signals_t(slc_signaller, "disable_signals()");
    NEW slf_signaller_clear_callbacks_t(slc_signaller, "clear_callbacks()");
    NEW slf_signaller_clear_callback_t(slc_signaller, "clear_callback(str)");
}
